const express = require('express');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();

app.get('/api/settings/notifications/:settingId', async (req, res) => {
  if (!req.user || !req.user.id) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Strictly enforce userId filter alongside settingId
  const setting = await prisma.userNotificationSetting.findFirst({
    where: {
      id: req.params.settingId,
      userId: req.user.id
    }
  });

  if (!setting) {
    return res.status(404).json({ error: 'Notification settings not found or access denied' });
  }

  res.json({ setting });
});

app.listen(4045);
